window.C3KO_DATA = {"version":1,"levels":[{"id":"A1","name":["Beginner","Pemula"],"goal":["Introduce yourself, talk about daily life, ask and answer simple questions.","Memperkenalkan diri, membicarakan kehidupan sehari-hari, bertanya dan menjawab hal sederhana."],"topics":[{"id":"a1-sounds","title":["Alphabet, pronunciation & capital letters","Alfabet, pelafalan & huruf kapital"],"what":["German is mostly read as it is written. A few letter groups have fixed sounds (ei, ie, eu, sch, ch), the umlauts ä, ö, ü change the vowel, and ß is a sharp s. All nouns are written with a capital letter.","Bahasa Jerman sebagian besar dibaca sesuai tulisannya. Beberapa gabungan huruf punya bunyi tetap (ei, ie, eu, sch, ch), umlaut ä, ö, ü mengubah vokal, dan ß adalah s tajam. Semua kata benda ditulis dengan huruf kapital."],"pattern":[{"head":[["Spelling","Ejaan"],["Sound","Bunyi"],["Example","Contoh"]],"rows":[["{ei}",["'eye'","'ai'"],"mein, drei"],["{ie}",["long ee","i panjang"],"Liebe, vier"],["{eu} / {äu}",["'oy'","'oi'"],"neu, Häuser"],["{ä}",["like e in 'bed'","seperti e dalam 'bebek'"],"Käse, spät"],["{ö}",["e with rounded lips","e dengan bibir bulat"],"schön, hören"],["{ü}",["i with rounded lips","i dengan bibir bulat"],"für, Tür"],["{sch}",["sh","sy"],"Schule, schön"],["{st-} / {sp-} (start)",["sht / shp","syt / syp"],"Straße, Sport"],["{ch}",["soft (ich) or throaty (ach)","lembut (ich) atau tenggorokan (ach)"],"ich, Buch"],["{w} / {v} / {z}",["v / f / ts","v / f / ts"],"Wasser, Vater, Zeit"],["{ß}",["sharp s","s tajam"],"Straße, heißen"]],"note":["Final b, d, g sound like p, t, k: Kind (kint), Tag (tak).","b, d, g di akhir kata berbunyi p, t, k: Kind (kint), Tag (tak)."]}],"examples":[["Guten Tag! Ich heiße Anna.",["Hello! My name is Anna.","Selamat siang! Nama saya Anna."]],["Wie geht es Ihnen? — Gut, danke.",["How are you? — Fine, thanks.","Apa kabar Anda? — Baik, terima kasih."]],["Das ist meine Straße.",["This is my street.","Ini jalan saya."]]],"tip":["Capitalise every noun, not only names: der Tisch, die Zeit, das Wasser. Sie with a capital S means polite 'you'.","Tulis setiap kata benda dengan huruf kapital, bukan hanya nama: der Tisch, die Zeit, das Wasser. Sie dengan S kapital berarti 'Anda'."]},{"id":"a1-pronouns","title":["Personal pronouns & du vs Sie","Kata ganti orang & du vs Sie"],"what":["German has an informal 'you' (du, ihr) and a polite 'you' (Sie, always capitalised) for one or more people. Sie (polite) uses the same verb form as sie (they). sie can also mean 'she' — the verb ending tells you which.","Bahasa Jerman punya 'kamu' informal (du, ihr) dan 'Anda' sopan (Sie, selalu kapital) untuk satu orang atau lebih. Sie (sopan) memakai bentuk kata kerja yang sama dengan sie (mereka). sie juga bisa berarti 'dia (perempuan)' — akhiran kata kerjanya yang menunjukkan."],"pattern":[{"head":[["Person","Persona"],["Singular","Tunggal"],["Plural","Jamak"]],"rows":[["1","{ich}","{wir}"],[["2 informal","2 informal"],"{du}","{ihr}"],["3","{er} / {sie} / {es}","{sie}"],[["polite (sg. + pl.)","sopan (tg. + jm.)"],"{Sie}","{Sie}"]],"note":["er, sie, es follow the grammatical gender of the noun: der Tisch → er, die Lampe → sie, das Buch → es.","er, sie, es mengikuti gender gramatikal kata bendanya: der Tisch → er, die Lampe → sie, das Buch → es."]}],"examples":[["Woher kommst du? — Ich komme aus Indonesien.",["Where are you from? — I'm from Indonesia.","Kamu dari mana? — Saya dari Indonesia."]],["Sprechen Sie Englisch?",["Do you (polite) speak English?","Apakah Anda bisa berbahasa Inggris?"]],["Der Tisch? Er ist neu.",["The table? It's new.","Mejanya? Itu baru."]]],"tip":["Use Sie with adults you don't know and in shops or offices; use du with friends, family, children and often colleagues of your age.","Pakai Sie dengan orang dewasa yang tidak dikenal dan di toko atau kantor; pakai du dengan teman, keluarga, anak-anak dan sering rekan kerja sebaya."]},{"id":"a1-sein","title":["Sein (to be)","Sein (adalah)"],"what":["Sein is irregular in every form. It links the subject to a name, job, nationality, description or place. With a job or nationality there is no article: Ich bin Lehrerin.","Sein tidak beraturan di semua bentuk. Kata kerja ini menghubungkan subjek dengan nama, pekerjaan, kebangsaan, deskripsi atau tempat. Untuk pekerjaan atau kebangsaan tanpa artikel: Ich bin Lehrerin."],"pattern":[{"head":[["Person","Persona"],"sein",["Example","Contoh"]],"rows":[["ich","{bin}","Ich {bin} Student."],["du","{bist}","Du {bist} müde."],["er / sie / es","{ist}","Sie {ist} zu Hause."],["wir","{sind}","Wir {sind} aus Berlin."],["ihr","{seid}","Ihr {seid} sehr nett."],["sie / Sie","{sind}","Sind Sie Frau Weber?"]]}],"examples":[["Ich bin Ingenieur.",["I'm an engineer.","Saya insinyur."]],["Wo ist der Bahnhof?",["Where is the station?","Di mana stasiunnya?"]],["Das ist mein Bruder.",["This is my brother.","Ini saudara laki-laki saya."]]],"tip":["Don't confuse ihr seid (you are) and seit (since). And no article with jobs: 'Er ist Arzt', not 'Er ist ein Arzt'.","Jangan tertukar ihr seid (kalian adalah) dan seit (sejak). Tanpa artikel untuk pekerjaan: 'Er ist Arzt', bukan 'Er ist ein Arzt'."]},{"id":"a1-haben","title":["Haben (to have)","Haben (punya)"],"what":["Haben means 'to have'. It is slightly irregular (du hast, er hat). German uses haben in some expressions where English uses 'be': Hunger haben (be hungry), Zeit haben (have time), Recht haben (be right). The object after haben is in the accusative.","Haben berarti 'punya'. Bentuknya sedikit tidak beraturan (du hast, er hat). Bahasa Jerman memakai haben dalam beberapa ungkapan: Hunger haben (lapar), Zeit haben (punya waktu), Recht haben (benar). Objek setelah haben berbentuk akusatif."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"haben"],"rows":[["ich","{habe}"],["du","{hast}"],["er / sie / es","{hat}"],["wir","{haben}"],["ihr","{habt}"],["sie / Sie","{haben}"]]},{"title":["Expressions","Ungkapan"],"head":[["German","Jerman"],["Meaning","Arti"]],"rows":[["{Hunger} / {Durst} haben",["be hungry / thirsty","lapar / haus"]],["{Zeit} haben",["have time","punya waktu"]],["{Recht} haben",["be right","benar"]],["{Angst} haben (vor)",["be afraid (of)","takut (akan)"]],["{Lust} haben (auf)",["feel like","ingin, berselera"]]],"note":["Age uses sein: Ich bin 25 (Jahre alt).","Umur memakai sein: Ich bin 25 (Jahre alt)."]}],"examples":[["Ich habe zwei Schwestern.",["I have two sisters.","Saya punya dua saudara perempuan."]],["Hast du Hunger?",["Are you hungry?","Kamu lapar?"]],["Wir haben heute keine Zeit.",["We don't have time today.","Hari ini kami tidak punya waktu."]]],"tip":["For age German uses sein, not haben: 'Ich bin 30', never 'Ich habe 30 Jahre'.","Untuk umur bahasa Jerman memakai sein, bukan haben: 'Ich bin 30', jangan 'Ich habe 30 Jahre'."]},{"id":"a1-present","title":["Present tense: regular verbs","Kala kini: kata kerja beraturan"],"what":["Take the infinitive, remove -en (or -n), and add the endings. Verb stems ending in -t or -d add an extra e (du arbeitest, er arbeitet). Stems ending in s, ß, z only add -t for du (du heißt). The present also covers the near future: Morgen arbeite ich.","Ambil infinitif, buang -en (atau -n), lalu tambahkan akhirannya. Akar yang berakhiran -t atau -d mendapat tambahan e (du arbeitest, er arbeitet). Akar yang berakhiran s, ß, z hanya ditambah -t untuk du (du heißt). Kala kini juga dipakai untuk masa depan dekat: Morgen arbeite ich."],"pattern":[{"head":[["Person","Persona"],"machen","arbeiten","heißen",["Ending","Akhiran"]],"rows":[["ich","mach{e}","arbeit{e}","heiß{e}","-e"],["du","mach{st}","arbeit{est}","heiß{t}","-st"],["er / sie / es","mach{t}","arbeit{et}","heiß{t}","-t"],["wir","mach{en}","arbeit{en}","heiß{en}","-en"],["ihr","mach{t}","arbeit{et}","heiß{t}","-t"],["sie / Sie","mach{en}","arbeit{en}","heiß{en}","-en"]]}],"examples":[["Ich wohne in Hamburg.",["I live in Hamburg.","Saya tinggal di Hamburg."]],["Was machst du am Wochenende?",["What are you doing at the weekend?","Apa yang kamu lakukan akhir pekan ini?"]],["Sie arbeitet bei einer Bank.",["She works at a bank.","Dia bekerja di sebuah bank."]]],"tip":["German has no '-ing' form: 'Ich lerne' means both 'I learn' and 'I am learning'.","Bahasa Jerman tidak punya bentuk '-ing': 'Ich lerne' berarti 'saya belajar' sekaligus 'saya sedang belajar'."]},{"id":"a1-present-stem","title":["Present tense: stem-changing verbs","Kala kini: kata kerja dengan perubahan vokal"],"what":["Many strong verbs change their stem vowel in the du and er/sie/es forms only: e → i (sprechen), e → ie (lesen), a → ä (fahren), au → äu (laufen). The other forms are regular. Wissen and nehmen are also irregular.","Banyak kata kerja kuat mengubah vokal akarnya hanya pada bentuk du dan er/sie/es: e → i (sprechen), e → ie (lesen), a → ä (fahren), au → äu (laufen). Bentuk lainnya beraturan. Wissen dan nehmen juga tidak beraturan."],"pattern":[{"head":[["Person","Persona"],"sprechen (e → i)","lesen (e → ie)","fahren (a → ä)","nehmen","wissen"],"rows":[["ich","spreche","lese","fahre","nehme","{weiß}"],["du","spr{i}chst","l{ie}st","f{ä}hrst","{nimmst}","{weißt}"],["er / sie / es","spr{i}cht","l{ie}st","f{ä}hrt","{nimmt}","{weiß}"],["wir","sprechen","lesen","fahren","nehmen","wissen"],["ihr","sprecht","lest","fahrt","nehmt","wisst"],["sie / Sie","sprechen","lesen","fahren","nehmen","wissen"]],"note":["Also e → i: essen (isst), geben (gibt), helfen (hilft). e → ie: sehen (sieht). a → ä: schlafen (schläft), tragen (trägt), waschen (wäscht). au → äu: laufen (läuft).","Juga e → i: essen (isst), geben (gibt), helfen (hilft). e → ie: sehen (sieht). a → ä: schlafen (schläft), tragen (trägt), waschen (wäscht). au → äu: laufen (läuft)."]}],"examples":[["Sprichst du Deutsch?",["Do you speak German?","Kamu bisa berbahasa Jerman?"]],["Er fährt mit dem Bus.",["He goes by bus.","Dia naik bus."]],["Ich weiß es nicht.",["I don't know.","Saya tidak tahu."]]],"tip":["The change never happens in the ihr form: ihr sprecht, ihr fahrt (not 'ihr sprich', 'ihr fährt').","Perubahan tidak pernah terjadi pada bentuk ihr: ihr sprecht, ihr fahrt (bukan 'ihr sprich', 'ihr fährt')."]},{"id":"a1-gender","title":["Noun gender: der, die, das","Gender kata benda: der, die, das"],"what":["Every German noun is masculine (der), feminine (die) or neuter (das). The indefinite articles are ein (m./n.) and eine (f.). Gender is often unpredictable, but some endings are reliable. Compound nouns take the gender of the last part.","Setiap kata benda bahasa Jerman maskulin (der), feminin (die) atau netral (das). Artikel taktakrifnya ein (m./n.) dan eine (f.). Gender sering tidak bisa ditebak, tetapi beberapa akhiran bisa diandalkan. Kata majemuk memakai gender bagian terakhirnya."],"pattern":[{"title":["Articles (nominative)","Artikel (nominatif)"],"head":["",["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["the","takrif"],"{der} Mann","{die} Frau","{das} Kind","{die} Kinder"],[["a","taktakrif"],"{ein} Mann","{eine} Frau","{ein} Kind",["— Kinder","— Kinder"]]]},{"title":["Reliable endings","Akhiran yang bisa diandalkan"],"head":[["Gender","Gender"],["Endings","Akhiran"],["Examples","Contoh"]],"rows":[["der","-er (people), -ling, -ismus; days, months, seasons","der Lehrer, der Montag, der Winter"],["die","-ung, -heit, -keit, -schaft, -ion, -tät, -in","die Zeitung, die Freiheit, die Lehrerin"],["das","-chen, -lein, -ment, -um; infinitives as nouns","das Mädchen, das Zentrum, das Essen"],[["compound","majemuk"],["last part decides","bagian terakhir menentukan"],"die Haus{tür}, der Kinder{garten}"]]}],"examples":[["Der Tisch ist groß.",["The table is big.","Mejanya besar."]],["Das ist eine gute Idee.",["That's a good idea.","Itu ide yang bagus."]],["Das Mädchen heißt Lena.",["The girl's name is Lena.","Anak perempuan itu bernama Lena."]]],"tip":["Learn each noun with its article and plural: der Tisch, die Tische. Das Mädchen is neuter because of -chen, even though it means 'girl'.","Hafalkan setiap kata benda bersama artikel dan bentuk jamaknya: der Tisch, die Tische. Das Mädchen netral karena -chen, meskipun artinya 'anak perempuan'."]},{"id":"a1-plurals","title":["Plural of nouns","Bentuk jamak kata benda"],"what":["German has several plural patterns, and the article is always die in the plural. Some endings point to the pattern: feminine nouns usually add -(e)n; nouns ending in -er, -el, -en (m./n.) often add nothing; foreign words often add -s.","Bahasa Jerman punya beberapa pola jamak, dan artikelnya selalu die dalam bentuk jamak. Beberapa akhiran menunjukkan polanya: kata benda feminin biasanya ditambah -(e)n; kata benda berakhiran -er, -el, -en (m./n.) sering tidak berubah; kata serapan sering ditambah -s."],"pattern":[{"head":[["Pattern","Pola"],["Singular","Tunggal"],["Plural","Jamak"],["Typical for","Khas untuk"]],"rows":[["-(e)n","die Frau / die Lampe","die Frau{en} / die Lampe{n}",["most feminine nouns","kebanyakan kata benda feminin"]],["-e","der Tisch / der Tag","die Tisch{e} / die Tag{e}",["many masculine nouns","banyak kata benda maskulin"]],["¨-e","die Stadt / der Stuhl","die St{ä}dt{e} / die St{ü}hl{e}",["some masc. and fem. nouns","sebagian maskulin dan feminin"]],["-er / ¨-er","das Kind / das Buch","die Kind{er} / die B{ü}ch{er}",["many neuter nouns","banyak kata benda netral"]],[["no change / ¨","tetap / ¨"],"der Lehrer / die Mutter","die Lehrer / die M{ü}tter",["-er, -el, -en","-er, -el, -en"]],["-s","das Auto / das Handy","die Auto{s} / die Handy{s}",["foreign words, -a, -o","kata serapan, -a, -o"]]],"note":["-in becomes -innen: die Lehrerin → die Lehrerinnen.","-in menjadi -innen: die Lehrerin → die Lehrerinnen."]}],"examples":[["Ich habe zwei Kinder.",["I have two children.","Saya punya dua anak."]],["Die Bücher sind auf dem Tisch.",["The books are on the table.","Buku-bukunya ada di atas meja."]],["Wie viele Äpfel möchtest du?",["How many apples would you like?","Kamu mau berapa apel?"]]],"tip":["Plural 'some' has no article: ein Apfel → Äpfel. Ich kaufe Äpfel (I'm buying apples).","Jamak 'beberapa' tanpa artikel: ein Apfel → Äpfel. Ich kaufe Äpfel (saya membeli apel)."]},{"id":"a1-accusative","title":["Nominative and accusative","Nominatif dan akusatif"],"what":["The subject is in the nominative; the direct object (what you have, see, buy, need…) is in the accusative. Only masculine articles change: der → den, ein → einen, kein → keinen. Feminine, neuter and plural stay the same. Prepositions durch, für, gegen, ohne, um always take the accusative.","Subjek berbentuk nominatif; objek langsung (yang dimiliki, dilihat, dibeli, dibutuhkan…) berbentuk akusatif. Hanya artikel maskulin yang berubah: der → den, ein → einen, kein → keinen. Feminin, netral dan jamak tetap. Kata depan durch, für, gegen, ohne, um selalu diikuti akusatif."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["nominative (subject)","nominatif (subjek)"],"der / ein / kein","die / eine / keine","das / ein / kein","die / — / keine"],[["accusative (object)","akusatif (objek)"],"{den} / {einen} / {keinen}","die / eine / keine","das / ein / kein","die / — / keine"],[["pronouns","kata ganti"],"er → {ihn}","sie → sie","es → es","sie → sie"]],"note":["Accusative pronouns: mich, dich, ihn, sie, es, uns, euch, sie, Sie.","Kata ganti akusatif: mich, dich, ihn, sie, es, uns, euch, sie, Sie."]}],"examples":[["Ich habe einen Bruder.",["I have a brother.","Saya punya satu saudara laki-laki."]],["Siehst du den Hund?",["Do you see the dog?","Kamu lihat anjing itu?"]],["Das Geschenk ist für dich.",["The present is for you.","Hadiahnya untukmu."]]],"tip":["Ask 'who or what is doing it?' (nominative) and 'whom or what is it done to?' (accusative). Es gibt also takes the accusative: Es gibt einen Park.","Tanyakan 'siapa yang melakukan?' (nominatif) dan 'siapa/apa yang dikenai?' (akusatif). Es gibt juga diikuti akusatif: Es gibt einen Park."]},{"id":"a1-negation","title":["Negation: nicht or kein?","Negasi: nicht atau kein?"],"what":["Kein negates a noun that would have ein or no article: Ich habe keine Zeit. It takes the same endings as ein (plus a plural form keine). Nicht negates everything else: verbs, adjectives, names, nouns with der/die/das or a possessive.","Kein menegasikan kata benda yang seharusnya memakai ein atau tanpa artikel: Ich habe keine Zeit. Akhirannya sama dengan ein (ditambah bentuk jamak keine). Nicht menegasikan selain itu: kata kerja, kata sifat, nama, kata benda dengan der/die/das atau kata kepemilikan."],"pattern":[{"head":[["Positive","Positif"],["Negative","Negatif"],["Rule","Aturan"]],"rows":[["Ich habe ein Auto.","Ich habe {kein} Auto.",["ein + noun → kein","ein + kata benda → kein"]],["Ich habe Zeit.","Ich habe {keine} Zeit.",["no article → kein","tanpa artikel → kein"]],["Das sind Äpfel.","Das sind {keine} Äpfel.",["plural → keine","jamak → keine"]],["Ich arbeite heute.","Ich arbeite heute {nicht}.",["verb → nicht (at the end)","kata kerja → nicht (di akhir)"]],["Das ist teuer.","Das ist {nicht} teuer.",["adjective → nicht before it","kata sifat → nicht sebelumnya"]],["Das ist der Bus.","Das ist {nicht} der Bus.",["der/die/das → nicht","der/die/das → nicht"]]]}],"examples":[["Ich spreche nicht gut Deutsch.",["I don't speak German well.","Saya tidak lancar berbahasa Jerman."]],["Er hat keinen Hund.",["He doesn't have a dog.","Dia tidak punya anjing."]],["Das ist nicht mein Handy.",["That's not my phone.","Itu bukan ponsel saya."]]],"tip":["Never 'nicht ein': use kein. 'Ich habe nicht einen Bruder' is wrong; say 'Ich habe keinen Bruder'.","Jangan 'nicht ein': pakai kein. 'Ich habe nicht einen Bruder' salah; katakan 'Ich habe keinen Bruder'."]},{"id":"a1-questions","title":["Questions: W-questions and yes/no questions","Pertanyaan: kata tanya W dan ya/tidak"],"what":["In a W-question, the question word comes first and the verb second. In a yes/no question, the verb comes first. Answer a negative question with doch to mean 'yes'.","Dalam pertanyaan dengan kata tanya W, kata tanya di awal dan kata kerja di posisi kedua. Dalam pertanyaan ya/tidak, kata kerja di awal. Jawab pertanyaan negatif dengan doch untuk berarti 'ya'."],"pattern":[{"title":["Word order","Susunan kata"],"head":[["Type","Jenis"],["Position 1","Posisi 1"],["Verb","Kata kerja"],["Rest","Sisanya"]],"rows":[[["W-question","Kata tanya W"],"{Wo}","{wohnst}","du?"],[["yes/no","ya/tidak"],"—","{Wohnst}","du in Berlin?"]]},{"title":["Question words","Kata tanya"],"head":[["German","Jerman"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{wer}",["who","siapa"],"Wer ist das?"],["{was}",["what","apa"],"Was machst du?"],["{wo} / {wohin} / {woher}",["where / where to / where from","di mana / ke mana / dari mana"],"Woher kommen Sie?"],["{wann}",["when","kapan"],"Wann beginnt der Kurs?"],["{wie}",["how","bagaimana"],"Wie heißt du?"],["{warum}",["why","mengapa"],"Warum lernst du Deutsch?"],["{wie viel} / {wie viele}",["how much / many","berapa"],"Wie viel kostet das?"],["{welcher / welche / welches}",["which","yang mana"],"Welche Farbe magst du?"]]}],"examples":[["Wie alt bist du?",["How old are you?","Berapa umurmu?"]],["Kommst du mit?",["Are you coming along?","Kamu ikut?"]],["Hast du keine Zeit? — Doch!",["Don't you have time? — Yes, I do!","Kamu tidak punya waktu? — Punya kok!"]]],"tip":["Wo = where (place), wohin = where to (direction), woher = where from. 'Wo gehst du?' is wrong; say 'Wohin gehst du?'.","Wo = di mana (tempat), wohin = ke mana (arah), woher = dari mana. 'Wo gehst du?' salah; katakan 'Wohin gehst du?'."]},{"id":"a1-word-order","title":["Word order: the verb in second position","Susunan kata: kata kerja di posisi kedua"],"what":["In a German statement, the conjugated verb is always the second element. If something other than the subject comes first (a time, a place, an object), the subject moves to after the verb. Infinitives and participles go to the end.","Dalam kalimat pernyataan bahasa Jerman, kata kerja terkonjugasi selalu menjadi unsur kedua. Jika yang di depan bukan subjek (waktu, tempat, objek), subjek pindah ke setelah kata kerja. Infinitif dan partisip diletakkan di akhir."],"pattern":[{"head":[["Position 1","Posisi 1"],["Verb (2)","Kata kerja (2)"],["Middle","Tengah"],["End","Akhir"]],"rows":[["Ich","{fahre}","morgen nach Berlin.","—"],["Morgen","{fahre}","ich nach Berlin.","—"],["Nach Berlin","{fahre}","ich morgen.","—"],["Ich","{möchte}","morgen nach Berlin","{fahren}."],["Heute","{stehe}","ich früh","{auf}."]],"note":["Order in the middle: usually time → manner → place (Te-Ka-Mo-Lo): Ich fahre morgen mit dem Zug nach Berlin.","Urutan di tengah: biasanya waktu → cara → tempat: Ich fahre morgen mit dem Zug nach Berlin."]}],"examples":[["Am Montag arbeite ich zu Hause.",["On Monday I work from home.","Hari Senin saya bekerja dari rumah."]],["Jetzt lerne ich Deutsch.",["Now I'm learning German.","Sekarang saya belajar bahasa Jerman."]],["Ich kann heute nicht kommen.",["I can't come today.","Saya tidak bisa datang hari ini."]]],"tip":["'Heute ich gehe' is the most common learner mistake: after a time word, the verb comes next: 'Heute gehe ich'. Und, aber, oder, denn do not count as position 1.","'Heute ich gehe' kesalahan paling umum: setelah kata waktu, kata kerja langsung menyusul: 'Heute gehe ich'. Und, aber, oder, denn tidak dihitung sebagai posisi 1."]},{"id":"a1-possessives","title":["Possessive articles (mein, dein…)","Artikel kepemilikan (mein, dein…)"],"what":["Possessives take the same endings as ein / kein: mein (m./n.), meine (f./pl.), meinen (masculine accusative). Choose the word by the owner, and the ending by the noun.","Kata kepemilikan memakai akhiran yang sama dengan ein / kein: mein (m./n.), meine (f./jm.), meinen (akusatif maskulin). Pilih katanya menurut pemilik, dan akhirannya menurut kata benda."],"pattern":[{"head":[["Owner","Pemilik"],["masc. / neut.","mask. / netral"],["fem. / plural","fem. / jamak"],["masc. acc.","akusatif mask."]],"rows":[["ich","{mein} Bruder","{meine} Schwester","{meinen} Bruder"],["du","{dein} Vater","{deine} Mutter","{deinen} Vater"],["er / es","{sein} Sohn","{seine} Tochter","{seinen} Sohn"],["sie (she)","{ihr} Sohn","{ihre} Tochter","{ihren} Sohn"],["wir","{unser} Haus","{unsere} Wohnung","{unseren} Garten"],["ihr","{euer} Hund","{eure} Katze","{euren} Hund"],["sie (they) / Sie","{ihr} / {Ihr} Auto","{ihre} / {Ihre} Kinder","{ihren} / {Ihren} Pass"]]}],"examples":[["Das ist meine Frau.",["This is my wife.","Ini istri saya."]],["Ich besuche meinen Onkel.",["I'm visiting my uncle.","Saya mengunjungi paman saya."]],["Ist das Ihr Koffer?",["Is this your (polite) suitcase?","Apakah ini koper Anda?"]]],"tip":["sein = his / its, ihr = her / their, Ihr = your (polite). Euer loses its e when an ending is added: eure, euren.","sein = miliknya (laki-laki/benda), ihr = miliknya (perempuan) / milik mereka, Ihr = milik Anda. Euer kehilangan e saat diberi akhiran: eure, euren."]},{"id":"a1-modals","title":["Modal verbs (können, müssen, wollen…)","Kata kerja modal (können, müssen, wollen…)"],"what":["Modal verbs express ability, obligation, wish and permission. They are irregular in the singular, and ich and er have the same form (no -t). The second verb goes to the end of the sentence as an infinitive.","Kata kerja modal menyatakan kemampuan, keharusan, keinginan dan izin. Bentuk tunggalnya tidak beraturan, dan bentuk ich dan er sama (tanpa -t). Kata kerja kedua diletakkan di akhir kalimat sebagai infinitif."],"pattern":[{"head":[["Person","Persona"],["können (can)","können (bisa)"],["müssen (must)","müssen (harus)"],["wollen (want)","wollen (mau)"],["dürfen (may)","dürfen (boleh)"],["möchten (would like)","möchten (ingin)"]],"rows":[["ich","{kann}","{muss}","{will}","{darf}","möchte"],["du","{kannst}","{musst}","{willst}","{darfst}","möchtest"],["er / sie / es","{kann}","{muss}","{will}","{darf}","möchte"],["wir","können","müssen","wollen","dürfen","möchten"],["ihr","könnt","müsst","wollt","dürft","möchtet"],["sie / Sie","können","müssen","wollen","dürfen","möchten"]],"note":["Also sollen (should): soll, sollst, soll. 'Nicht müssen' = don't have to; 'nicht dürfen' = must not.","Juga sollen (sebaiknya): soll, sollst, soll. 'Nicht müssen' = tidak perlu; 'nicht dürfen' = tidak boleh."]}],"examples":[["Ich kann gut schwimmen.",["I can swim well.","Saya bisa berenang dengan baik."]],["Du musst morgen früh aufstehen.",["You have to get up early tomorrow.","Kamu harus bangun pagi besok."]],["Ich möchte einen Kaffee, bitte.",["I'd like a coffee, please.","Saya mau kopi, tolong."]]],"tip":["Hier darf man nicht rauchen = smoking is not allowed. Du musst nicht kommen = you don't have to come (but you may).","Hier darf man nicht rauchen = dilarang merokok. Du musst nicht kommen = kamu tidak perlu datang (tetapi boleh)."]},{"id":"a1-separable","title":["Separable verbs (aufstehen, einkaufen)","Kata kerja terpisah (aufstehen, einkaufen)"],"what":["Many verbs have a stressed prefix (an-, auf-, aus-, ein-, mit-, zu-, fern-…) that separates in the present and goes to the end of the clause. With a modal verb, the verb stays together at the end as an infinitive.","Banyak kata kerja punya awalan bertekanan (an-, auf-, aus-, ein-, mit-, zu-, fern-…) yang terpisah di kala kini dan pindah ke akhir klausa. Dengan kata kerja modal, kata kerjanya tetap utuh di akhir sebagai infinitif."],"pattern":[{"head":[["Infinitive","Infinitif"],["Statement","Pernyataan"],["Question","Pertanyaan"],["With a modal","Dengan modal"]],"rows":[["{auf}stehen","Ich stehe um 7 Uhr {auf}.","Wann stehst du {auf}?","Ich muss früh {auf}stehen."],["{ein}kaufen","Wir kaufen heute {ein}.","Kaufst du {ein}?","Ich will {ein}kaufen."],["{an}rufen","Ich rufe dich morgen {an}.","Rufst du mich {an}?","Kannst du mich {an}rufen?"],["{fern}sehen","Er sieht jeden Abend {fern}.","Siehst du {fern}?","Wir wollen {fern}sehen."],["{mit}kommen","Kommst du {mit}?","—","Ich möchte {mit}kommen."]],"note":["Inseparable prefixes (be-, ver-, er-, ent-, ge-, zer-, emp-) never separate: Ich verstehe, ich bekomme.","Awalan tak terpisah (be-, ver-, er-, ent-, ge-, zer-, emp-) tidak pernah terpisah: Ich verstehe, ich bekomme."]}],"examples":[["Der Film fängt um acht Uhr an.",["The film starts at eight.","Filmnya mulai pukul delapan."]],["Ich kaufe im Supermarkt ein.",["I do the shopping at the supermarket.","Saya berbelanja di supermarket."]],["Kommst du mit ins Kino?",["Are you coming to the cinema with us?","Kamu ikut ke bioskop?"]]],"tip":["Don't forget the prefix at the end: 'Ich stehe um 7 Uhr auf'. Without auf, 'Ich stehe' means 'I'm standing'.","Jangan lupa awalan di akhir: 'Ich stehe um 7 Uhr auf'. Tanpa auf, 'Ich stehe' berarti 'saya berdiri'."]},{"id":"a1-numbers-time","title":["Numbers, prices & telling the time","Angka, harga & menyebut jam"],"what":["From 21 to 99, German says the unit first: einundzwanzig (one-and-twenty). In everyday time, halb means 'half to' the next hour: halb drei = 2:30. The 24-hour clock is used for timetables: 14:30 = vierzehn Uhr dreißig.","Dari 21 sampai 99, bahasa Jerman menyebut satuan dulu: einundzwanzig (satu-dan-dua puluh). Dalam jam sehari-hari, halb berarti 'setengah menuju' jam berikutnya: halb drei = 2.30. Sistem 24 jam dipakai untuk jadwal: 14.30 = vierzehn Uhr dreißig."],"pattern":[{"title":["Numbers","Angka"],"head":["","","",""],"rows":[["1 eins","11 elf","21 {einund}zwanzig","60 {sech}zig"],["2 zwei","12 zwölf","30 {dreißig}","70 {sieb}zig"],["3 drei","13 dreizehn","35 {fünfund}dreißig","100 (ein)hundert"],["6 sechs","16 {sech}zehn","40 vierzig","101 hunderteins"],["7 sieben","17 {sieb}zehn","50 fünfzig","1000 (ein)tausend"]]},{"title":["Telling the time (everyday)","Menyebut jam (sehari-hari)"],"head":[["Time","Jam"],["German","Jerman"]],"rows":[["3:00","Es ist drei {Uhr}."],["3:15","Es ist {Viertel nach} drei."],["3:30","Es ist {halb vier}."],["3:45","Es ist {Viertel vor} vier."],["3:10 / 3:50","zehn {nach} drei / zehn {vor} vier"],[["at 8:00","pukul 8:00"],"{um} acht Uhr"]]}],"examples":[["Wie spät ist es? — Es ist halb sieben.",["What time is it? — It's half past six.","Jam berapa? — Pukul setengah tujuh."]],["Der Zug fährt um 14:20 Uhr.",["The train leaves at 14:20.","Keretanya berangkat pukul 14.20."]],["Das kostet neunundzwanzig Euro.",["That costs twenty-nine euros.","Harganya dua puluh sembilan euro."]]],"tip":["'Halb acht' is 7:30, not 8:30. And 'at' + time is um: um neun Uhr.","'Halb acht' adalah 7.30, bukan 8.30. 'Pada pukul' adalah um: um neun Uhr."]},{"id":"a1-prep-time","title":["Prepositions of time: um, am, im, von … bis","Kata depan waktu: um, am, im, von … bis"],"what":["Um is for clock times, am (an dem) for days, dates and parts of the day, im (in dem) for months, seasons and longer periods. Years usually take no preposition. Von … bis (from … until) and ab (from) give ranges.","Um untuk jam, am (an dem) untuk hari, tanggal dan bagian hari, im (in dem) untuk bulan, musim dan periode yang lebih panjang. Tahun biasanya tanpa kata depan. Von … bis (dari … sampai) dan ab (mulai) untuk rentang."],"pattern":[{"head":[["Preposition","Kata depan"],["Used with","Dipakai dengan"],["Example","Contoh"]],"rows":[["{um}",["clock time","jam"],"{um} 8 Uhr"],["{am}",["days, dates, parts of the day","hari, tanggal, bagian hari"],"{am} Montag, {am} 3. Mai, {am} Abend"],["{im}",["months, seasons","bulan, musim"],"{im} Juli, {im} Winter"],["—",["years","tahun"],"2026 / im Jahr 2026"],["{in der Nacht}",["at night","malam hari"],"{in der Nacht}"],["{von} … {bis}",["from … until","dari … sampai"],"{von} 9 {bis} 17 Uhr"]]}],"examples":[["Ich arbeite von Montag bis Freitag.",["I work from Monday to Friday.","Saya bekerja dari Senin sampai Jumat."]],["Am Wochenende schlafe ich lange.",["At the weekend I sleep in.","Akhir pekan saya tidur lama."]],["Im Sommer fahren wir ans Meer.",["In summer we go to the seaside.","Musim panas kami pergi ke pantai."]]],"tip":["Say 'in 2026' as just '2026' or 'im Jahr 2026', never 'in 2026'. For the night use in der Nacht, not am Nacht.","Untuk tahun cukup '2026' atau 'im Jahr 2026', jangan 'in 2026'. Untuk malam pakai in der Nacht, bukan am Nacht."]}]},{"id":"A2","name":["Elementary","Dasar"],"goal":["Talk about the past, give reasons, describe people and places; deal with everyday situations.","Membicarakan masa lalu, memberi alasan, menggambarkan orang dan tempat; mengatasi situasi sehari-hari."],"topics":[{"id":"a2-perfekt-haben","title":["Perfekt with haben","Perfekt dengan haben"],"what":["The Perfekt is the normal spoken past tense: haben (or sein) in the present + Partizip II at the end of the clause. Weak verbs: ge- + stem + -t (gemacht). Strong verbs: ge- + (changed) stem + -en (gesehen). Verbs in -ieren and verbs with be-, ver-, er-, ent- have no ge-.","Perfekt adalah kala lampau yang biasa dipakai dalam percakapan: haben (atau sein) dalam kala kini + Partizip II di akhir klausa. Kata kerja lemah: ge- + akar + -t (gemacht). Kata kerja kuat: ge- + akar (berubah) + -en (gesehen). Kata kerja -ieren dan yang berawalan be-, ver-, er-, ent- tanpa ge-."],"pattern":[{"title":["Partizip II","Partizip II"],"head":[["Type","Jenis"],["Infinitive","Infinitif"],["Partizip II","Partizip II"]],"rows":[[["weak","lemah"],"machen / arbeiten","{ge}mach{t} / {ge}arbeit{et}"],[["strong","kuat"],"sehen / trinken","{ge}seh{en} / {ge}trunk{en}"],[["mixed","campuran"],"bringen / denken","{ge}brach{t} / {ge}dach{t}"],[["separable","terpisah"],"einkaufen / anrufen","ein{ge}kauft / an{ge}rufen"],[["no ge-","tanpa ge-"],"besuchen / verstehen / studieren","besucht / verstanden / studiert"]]},{"title":["Sentence","Kalimat"],"head":[["Position 1","Posisi 1"],["haben (2)","haben (2)"],["Middle","Tengah"],["End","Akhir"]],"rows":[["Ich","{habe}","gestern Pizza","{gegessen}."],["Gestern","{hat}","er lange","{gearbeitet}."],["—","{Hast}","du den Film","{gesehen}?"]]}],"examples":[["Ich habe gestern viel gearbeitet.",["I worked a lot yesterday.","Kemarin saya banyak bekerja."]],["Hast du schon gegessen?",["Have you eaten yet?","Kamu sudah makan?"]],["Wir haben Oma besucht.",["We visited Grandma.","Kami mengunjungi nenek."]]],"tip":["The participle always goes to the end: 'Ich habe das Buch gelesen', never 'Ich habe gelesen das Buch'.","Partisip selalu di akhir: 'Ich habe das Buch gelesen', jangan 'Ich habe gelesen das Buch'."]},{"id":"a2-perfekt-sein","title":["Perfekt with sein","Perfekt dengan sein"],"what":["Verbs of movement from one place to another (gehen, fahren, fliegen, kommen) and of change of state (aufstehen, einschlafen, sterben, werden) form the Perfekt with sein, as do sein and bleiben. They have no direct object.","Kata kerja gerakan dari satu tempat ke tempat lain (gehen, fahren, fliegen, kommen) dan perubahan keadaan (aufstehen, einschlafen, sterben, werden) membentuk Perfekt dengan sein, begitu juga sein dan bleiben. Kata kerja ini tidak punya objek langsung."],"pattern":[{"head":[["Group","Kelompok"],["Infinitive","Infinitif"],["Perfekt","Perfekt"]],"rows":[[["movement","gerakan"],"gehen / fahren / fliegen","{ist} gegangen / {ist} gefahren / {ist} geflogen"],[["movement","gerakan"],"kommen / laufen / reisen","{ist} gekommen / {ist} gelaufen / {ist} gereist"],[["change of state","perubahan keadaan"],"aufstehen / einschlafen / werden","{ist} aufgestanden / {ist} eingeschlafen / {ist} geworden"],[["exceptions","pengecualian"],"sein / bleiben / passieren","{ist} gewesen / {ist} geblieben / {ist} passiert"]],"note":["fahren with an object takes haben: Ich habe das Auto gefahren.","fahren dengan objek memakai haben: Ich habe das Auto gefahren."]}],"examples":[["Wir sind nach Wien gefahren.",["We went to Vienna.","Kami pergi ke Wina."]],["Ich bin um sieben Uhr aufgestanden.",["I got up at seven.","Saya bangun pukul tujuh."]],["Was ist passiert?",["What happened?","Apa yang terjadi?"]]],"tip":["Unlike French, the participle never changes with sein: 'Sie ist gegangen', 'Wir sind gegangen'.","Partisip tidak pernah berubah dengan sein: 'Sie ist gegangen', 'Wir sind gegangen'."]},{"id":"a2-praeteritum-basic","title":["Präteritum of sein, haben and modal verbs","Präteritum sein, haben dan kata kerja modal"],"what":["In speech, most verbs use the Perfekt for the past, but sein, haben and the modal verbs normally use the Präteritum (simple past): ich war, ich hatte, ich konnte. Ich and er have the same form (no ending).","Dalam percakapan, kebanyakan kata kerja memakai Perfekt untuk lampau, tetapi sein, haben dan kata kerja modal biasanya memakai Präteritum: ich war, ich hatte, ich konnte. Bentuk ich dan er sama (tanpa akhiran)."],"pattern":[{"head":[["Person","Persona"],"sein","haben","können","müssen","wollen"],"rows":[["ich","{war}","{hatte}","{konnte}","{musste}","{wollte}"],["du","{warst}","{hattest}","{konntest}","{musstest}","{wolltest}"],["er / sie / es","{war}","{hatte}","{konnte}","{musste}","{wollte}"],["wir","{waren}","{hatten}","{konnten}","{mussten}","{wollten}"],["ihr","{wart}","{hattet}","{konntet}","{musstet}","{wolltet}"],["sie / Sie","{waren}","{hatten}","{konnten}","{mussten}","{wollten}"]],"note":["Also: dürfen → durfte, sollen → sollte, mögen → mochte. Modal Präteritum has no umlaut. Es gab = there was / were.","Juga: dürfen → durfte, sollen → sollte, mögen → mochte. Präteritum modal tanpa umlaut. Es gab = dulu ada."]}],"examples":[["Gestern war ich krank.",["Yesterday I was ill.","Kemarin saya sakit."]],["Wir hatten keine Zeit.",["We didn't have time.","Kami tidak punya waktu."]],["Ich musste lange warten.",["I had to wait a long time.","Saya harus menunggu lama."]]],"tip":["'Ich bin gewesen' and 'ich habe gehabt' are correct but sound heavy; prefer 'ich war' and 'ich hatte'.","'Ich bin gewesen' dan 'ich habe gehabt' benar tetapi terdengar berat; lebih baik 'ich war' dan 'ich hatte'."]},{"id":"a2-dative","title":["The dative case","Kasus datif"],"what":["The dative marks the indirect object: the person who receives or benefits (to whom / for whom). Articles change in all genders: dem (m./n.), der (f.), den + -n (plural). Ein becomes einem / einer.","Datif menandai objek tak langsung: orang yang menerima atau mendapat manfaat (kepada / untuk siapa). Artikel berubah di semua gender: dem (m./n.), der (f.), den + -n (jamak). Ein menjadi einem / einer."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["nominative","nominatif"],"der / ein","die / eine","das / ein","die / —"],[["accusative","akusatif"],"den / einen","die / eine","das / ein","die / —"],[["dative","datif"],"{dem} / {einem}","{der} / {einer}","{dem} / {einem}","{den} Kinder{n} / —"]],"note":["Possessives and kein follow ein: meinem, meiner, keinem. Plural nouns add -n in the dative unless they end in -n or -s: den Kindern, den Autos.","Kata kepemilikan dan kein mengikuti ein: meinem, meiner, keinem. Kata benda jamak ditambah -n pada datif kecuali sudah berakhiran -n atau -s: den Kindern, den Autos."]}],"examples":[["Ich gebe dem Mann das Buch.",["I give the man the book.","Saya memberikan buku itu kepada laki-laki itu."]],["Sie schenkt ihrer Mutter Blumen.",["She gives her mother flowers.","Dia menghadiahkan bunga kepada ibunya."]],["Wir helfen den Kindern.",["We help the children.","Kami membantu anak-anak."]]],"tip":["With two objects, the dative person usually comes before the accusative thing: Ich gebe dem Kind (wem?) den Ball (was?).","Dengan dua objek, orang (datif) biasanya sebelum benda (akusatif): Ich gebe dem Kind den Ball."]},{"id":"a2-dative-verbs","title":["Verbs with the dative","Kata kerja dengan datif"],"what":["Some common verbs take a dative object even though English uses a direct object: helfen, danken, gefallen, gehören, antworten, gratulieren, schmecken, passen. Gefallen, gehören and schmecken work like 'please': the thing is the subject.","Beberapa kata kerja umum memakai objek datif meskipun bahasa Inggris memakai objek langsung: helfen, danken, gefallen, gehören, antworten, gratulieren, schmecken, passen. Gefallen, gehören dan schmecken bekerja seperti 'menyenangkan': bendanya menjadi subjek."],"pattern":[{"title":["Verbs","Kata kerja"],"head":[["Verb","Kata kerja"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["helfen",["help","membantu"],"Ich helfe {dir}."],["danken",["thank","berterima kasih"],"Ich danke {Ihnen}."],["gefallen",["please, like","menyenangkan, suka"],"Das Kleid gefällt {mir}."],["gehören",["belong to","milik"],"Das Buch gehört {meinem Bruder}."],["schmecken",["taste (good)","enak"],"Schmeckt {dir} die Suppe?"],["antworten",["answer","menjawab"],"Er antwortet {der Lehrerin} nicht."]]},{"title":["Dative pronouns","Kata ganti datif"],"head":["ich","du","er / es","sie","wir","ihr","sie / Sie"],"rows":[["{mir}","{dir}","{ihm}","{ihr}","{uns}","{euch}","{ihnen} / {Ihnen}"]]}],"examples":[["Kannst du mir helfen?",["Can you help me?","Bisakah kamu membantu saya?"]],["Wie geht es Ihnen?",["How are you? (polite)","Apa kabar Anda?"]],["Die Stadt gefällt mir sehr.",["I really like the city.","Saya sangat suka kota ini."]]],"tip":["'Wie geht es dir?' uses the dative too: es geht mir gut. Never 'Ich bin gut' for 'I'm fine'.","'Wie geht es dir?' juga memakai datif: es geht mir gut. Jangan 'Ich bin gut' untuk 'saya baik-baik saja'."]},{"id":"a2-prepositions","title":["Prepositions with accusative or dative","Kata depan dengan akusatif atau datif"],"what":["Some prepositions always take the accusative (durch, für, gegen, ohne, um) and some always the dative (aus, bei, mit, nach, seit, von, zu, gegenüber). Many merge with the article: zu dem → zum, zu der → zur, bei dem → beim, von dem → vom.","Beberapa kata depan selalu diikuti akusatif (durch, für, gegen, ohne, um) dan beberapa selalu datif (aus, bei, mit, nach, seit, von, zu, gegenüber). Banyak yang bergabung dengan artikel: zu dem → zum, zu der → zur, bei dem → beim, von dem → vom."],"pattern":[{"head":[["Case","Kasus"],["Prepositions","Kata depan"],["Example","Contoh"]],"rows":[[["accusative","akusatif"],"{durch, für, gegen, ohne, um}","für {den} Chef, ohne {meinen} Pass"],[["dative","datif"],"{aus, bei, mit, nach, seit, von, zu}","mit {dem} Bus, seit {einem} Jahr"],[["contractions","penggabungan"],"zum, zur, beim, vom","{zum} Arzt, {zur} Arbeit, {beim} Bäcker"]],"note":["nach = to (cities, countries without article, home: nach Hause); zu = to (people, shops, places: zum Arzt); bei = at (someone's place: bei mir).","nach = ke (kota, negara tanpa artikel, rumah: nach Hause); zu = ke (orang, toko, tempat: zum Arzt); bei = di (tempat seseorang: bei mir)."]}],"examples":[["Ich fahre mit dem Fahrrad zur Arbeit.",["I cycle to work.","Saya bersepeda ke tempat kerja."]],["Das Geschenk ist für meinen Vater.",["The present is for my father.","Hadiah ini untuk ayah saya."]],["Ich wohne seit drei Jahren in Köln.",["I've lived in Cologne for three years.","Saya sudah tinggal di Köln selama tiga tahun."]]],"tip":["Seit + present tense = 'have been … for/since': Ich lerne seit zwei Monaten Deutsch.","Seit + kala kini = 'sudah … selama/sejak': Ich lerne seit zwei Monaten Deutsch."]},{"id":"a2-two-way","title":["Two-way prepositions (in, an, auf…)","Kata depan dua arah (in, an, auf…)"],"what":["Nine prepositions (an, auf, hinter, in, neben, über, unter, vor, zwischen) take the accusative for movement towards a place (wohin?) and the dative for location (wo?). In + dem = im, in + das = ins, an + dem = am, an + das = ans.","Sembilan kata depan (an, auf, hinter, in, neben, über, unter, vor, zwischen) diikuti akusatif untuk gerakan menuju tempat (wohin?) dan datif untuk lokasi (wo?). In + dem = im, in + das = ins, an + dem = am, an + das = ans."],"pattern":[{"head":[["Question","Pertanyaan"],["Case","Kasus"],["Example","Contoh"]],"rows":[[["Wohin? (direction)","Wohin? (arah)"],["accusative","akusatif"],"Ich gehe {in den} Park. Ich lege das Buch {auf den} Tisch."],[["Wo? (location)","Wo? (lokasi)"],["dative","datif"],"Ich bin {im} Park. Das Buch liegt {auf dem} Tisch."],[["Wohin?","Wohin?"],["accusative","akusatif"],"Wir fahren {ans} Meer. Er geht {ins} Kino."],[["Wo?","Wo?"],["dative","datif"],"Wir sind {am} Meer. Er ist {im} Kino."]]}],"examples":[["Ich hänge das Bild an die Wand.",["I'm hanging the picture on the wall.","Saya menggantung gambar di dinding."]],["Das Bild hängt an der Wand.",["The picture is hanging on the wall.","Gambar itu tergantung di dinding."]],["Die Katze schläft unter dem Bett.",["The cat is sleeping under the bed.","Kucingnya tidur di bawah tempat tidur."]]],"tip":["Ask 'wohin?' (where to → accusative) or 'wo?' (where → dative). The verb often tells you: gehen, legen, stellen → wohin; sein, liegen, stehen → wo.","Tanyakan 'wohin?' (ke mana → akusatif) atau 'wo?' (di mana → datif). Kata kerjanya sering menunjukkan: gehen, legen, stellen → wohin; sein, liegen, stehen → wo."]},{"id":"a2-wo-wohin","title":["Position verbs: legen / liegen, stellen / stehen…","Kata kerja posisi: legen / liegen, stellen / stehen…"],"what":["German distinguishes putting something somewhere (weak verbs + accusative: legen, stellen, setzen, hängen) from being in a position (strong verbs + dative: liegen, stehen, sitzen, hängen). Things that lie flat use legen/liegen; upright things use stellen/stehen.","Bahasa Jerman membedakan menaruh sesuatu (kata kerja lemah + akusatif: legen, stellen, setzen, hängen) dari berada di suatu posisi (kata kerja kuat + datif: liegen, stehen, sitzen, hängen). Benda yang berbaring memakai legen/liegen; benda tegak memakai stellen/stehen."],"pattern":[{"head":[["Action (wohin? + acc.)","Tindakan (wohin? + akus.)"],["Position (wo? + dat.)","Posisi (wo? + dat.)"],["Example","Contoh"]],"rows":[["{legen} (hat gelegt)","{liegen} (hat gelegen)","Ich lege das Handy auf den Tisch. → Es liegt auf dem Tisch."],["{stellen} (hat gestellt)","{stehen} (hat gestanden)","Ich stelle die Flasche in den Kühlschrank. → Sie steht im Kühlschrank."],["{setzen} (hat gesetzt)","{sitzen} (hat gesessen)","Ich setze mich aufs Sofa. → Ich sitze auf dem Sofa."],["{hängen} (hat gehängt)","{hängen} (hat gehangen)","Ich hänge die Jacke in den Schrank. → Sie hängt im Schrank."]]}],"examples":[["Wo liegt mein Schlüssel?",["Where is my key (lying)?","Di mana kunci saya?"]],["Stell die Vase auf den Tisch.",["Put the vase on the table.","Taruh vas itu di atas meja."]],["Wir sitzen im Garten.",["We're sitting in the garden.","Kami duduk di kebun."]]],"tip":["Where English says 'is', German often uses liegen or stehen: Das Buch liegt auf dem Tisch. Berlin liegt an der Spree.","Untuk 'ada di', bahasa Jerman sering memakai liegen atau stehen: Das Buch liegt auf dem Tisch. Berlin liegt an der Spree."]},{"id":"a2-adj-definite","title":["Adjective endings after der, die, das","Akhiran kata sifat setelah der, die, das"],"what":["An adjective before a noun needs an ending. After der/die/das (and dieser, jeder, welcher) there are only two endings: -e and -en. Use -e in the five 'basic' slots (nominative singular, plus accusative feminine and neuter); everywhere else -en.","Kata sifat sebelum kata benda memerlukan akhiran. Setelah der/die/das (dan dieser, jeder, welcher) hanya ada dua akhiran: -e dan -en. Pakai -e di lima posisi 'dasar' (nominatif tunggal, serta akusatif feminin dan netral); di tempat lain -en."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["nominative","nominatif"],"der neu{e} Tisch","die neu{e} Lampe","das neu{e} Bett","die neu{en} Stühle"],[["accusative","akusatif"],"den neu{en} Tisch","die neu{e} Lampe","das neu{e} Bett","die neu{en} Stühle"],[["dative","datif"],"dem neu{en} Tisch","der neu{en} Lampe","dem neu{en} Bett","den neu{en} Stühlen"]],"note":["After the verb (predicative) adjectives have no ending: Der Tisch ist neu.","Setelah kata kerja (predikatif) kata sifat tanpa akhiran: Der Tisch ist neu."]}],"examples":[["Der alte Mann wohnt hier.",["The old man lives here.","Laki-laki tua itu tinggal di sini."]],["Ich nehme die rote Jacke.",["I'll take the red jacket.","Saya ambil jaket merah itu."]],["Sie wohnt in dem großen Haus.",["She lives in the big house.","Dia tinggal di rumah besar itu."]]],"tip":["Plural after die is always -en: die guten Freunde, never 'die gute Freunde'.","Jamak setelah die selalu -en: die guten Freunde, jangan 'die gute Freunde'."]},{"id":"a2-adj-indefinite","title":["Adjective endings after ein, kein, mein","Akhiran kata sifat setelah ein, kein, mein"],"what":["After ein, kein and possessives, the article sometimes has no ending of its own (ein, kein, mein). In those three slots the adjective shows the gender: -er (masc. nominative), -es (neuter nom./acc.). Otherwise the endings are the same as after der/die/das.","Setelah ein, kein dan kata kepemilikan, artikelnya kadang tanpa akhiran sendiri (ein, kein, mein). Di tiga posisi itu kata sifat menunjukkan gendernya: -er (nominatif maskulin), -es (netral nom./akus.). Selain itu akhirannya sama dengan setelah der/die/das."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural (kein / mein)","jamak (kein / mein)"]],"rows":[[["nominative","nominatif"],"ein neu{er} Tisch","eine neu{e} Lampe","ein neu{es} Bett","meine neu{en} Stühle"],[["accusative","akusatif"],"einen neu{en} Tisch","eine neu{e} Lampe","ein neu{es} Bett","meine neu{en} Stühle"],[["dative","datif"],"einem neu{en} Tisch","einer neu{en} Lampe","einem neu{en} Bett","meinen neu{en} Stühlen"]]}],"examples":[["Das ist ein guter Film.",["That's a good film.","Itu film yang bagus."]],["Ich habe ein kleines Auto.",["I have a small car.","Saya punya mobil kecil."]],["Er wohnt mit seiner neuen Freundin zusammen.",["He lives with his new girlfriend.","Dia tinggal bersama pacar barunya."]]],"tip":["Compare: der gute Wein but ein guter Wein; das kleine Haus but ein kleines Haus. When the article doesn't show the gender, the adjective does.","Bandingkan: der gute Wein tetapi ein guter Wein; das kleine Haus tetapi ein kleines Haus. Jika artikel tidak menunjukkan gender, kata sifatlah yang menunjukkannya."]},{"id":"a2-comparison","title":["Comparatives & superlatives","Perbandingan & superlatif"],"what":["Add -er for the comparative (schneller) and use als for 'than'. For 'as … as' use so … wie. The superlative is am …-sten after a verb (am schnellsten) or der/die/das …-ste before a noun. Many short adjectives add an umlaut, and a few are irregular.","Tambahkan -er untuk komparatif (schneller) dan pakai als untuk 'daripada'. Untuk 'se…' pakai so … wie. Superlatif = am …-sten setelah kata kerja (am schnellsten) atau der/die/das …-ste sebelum kata benda. Banyak kata sifat pendek mendapat umlaut, dan beberapa tidak beraturan."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Base","Dasar"],["Comparative","Komparatif"],["Superlative","Superlatif"]],"rows":[["schnell","schnell{er}","am schnell{sten}"],["alt / groß","{ä}lt{er} / gr{ö}ß{er}","am {ä}lte{sten} / am gr{ö}ß{ten}"],["gut","{besser}","am {besten}"],["viel","{mehr}","am {meisten}"],["gern","{lieber}","am {liebsten}"],["hoch","{höher}","am {höchsten}"]]},{"title":["Patterns","Pola"],"head":[["Meaning","Arti"],["Pattern","Pola"],["Example","Contoh"]],"rows":[[["more … than","lebih … daripada"],"…-er {als}","Berlin ist größer {als} München."],[["as … as","se… / sama … dengan"],"{so} … {wie}","Er ist {so} groß {wie} sein Vater."],[["the most","paling"],"{am} …-sten / der …-ste","Sie läuft {am schnellsten}. Das ist der {beste} Kuchen."]]}],"examples":[["Mein Bruder ist älter als ich.",["My brother is older than me.","Kakak laki-laki saya lebih tua dari saya."]],["Ich trinke lieber Tee als Kaffee.",["I prefer tea to coffee.","Saya lebih suka teh daripada kopi."]],["Das ist das beste Restaurant der Stadt.",["That's the best restaurant in town.","Itu restoran terbaik di kota."]]],"tip":["'Than' is als, not wie or dann: größer als. Wie is only for equality: so groß wie.","'Daripada' adalah als, bukan wie atau dann: größer als. Wie hanya untuk kesamaan: so groß wie."]},{"id":"a2-reflexive","title":["Reflexive verbs (sich freuen, sich waschen)","Kata kerja refleksif (sich freuen, sich waschen)"],"what":["Reflexive verbs use a pronoun that refers back to the subject. It is usually accusative (mich, dich, sich…), but dative (mir, dir) when there is another direct object: ich wasche mich / ich wasche mir die Hände. Sich is used for er, sie, es, sie and Sie.","Kata kerja refleksif memakai kata ganti yang merujuk kembali ke subjek. Biasanya akusatif (mich, dich, sich…), tetapi datif (mir, dir) jika ada objek langsung lain: ich wasche mich / ich wasche mir die Hände. Sich dipakai untuk er, sie, es, sie dan Sie."],"pattern":[{"head":[["Person","Persona"],["Accusative","Akusatif"],["Dative","Datif"],["Example","Contoh"]],"rows":[["ich","{mich}","{mir}","Ich freue {mich}."],["du","{dich}","{dir}","Wasch {dir} die Hände!"],["er / sie / es","{sich}","{sich}","Er zieht {sich} an."],["wir","{uns}","{uns}","Wir treffen {uns} um acht."],["ihr","{euch}","{euch}","Beeilt {euch}!"],["sie / Sie","{sich}","{sich}","Setzen Sie {sich}, bitte."]],"note":["Common: sich freuen (auf/über), sich interessieren für, sich erinnern an, sich beeilen, sich ausruhen, sich fühlen, sich vorstellen.","Umum: sich freuen (auf/über), sich interessieren für, sich erinnern an, sich beeilen, sich ausruhen, sich fühlen, sich vorstellen."]}],"examples":[["Ich freue mich auf das Wochenende.",["I'm looking forward to the weekend.","Saya menantikan akhir pekan."]],["Interessierst du dich für Musik?",["Are you interested in music?","Kamu tertarik dengan musik?"]],["Wie fühlen Sie sich?",["How do you feel?","Bagaimana perasaan Anda?"]]],"tip":["Sich freuen auf = look forward to (future); sich freuen über = be happy about (now/past).","Sich freuen auf = menantikan (masa depan); sich freuen über = senang atas (sekarang/lampau)."]},{"id":"a2-subordinate","title":["Subordinate clauses: weil, dass, wenn","Anak kalimat: weil, dass, wenn"],"what":["Subordinating conjunctions (weil, dass, wenn, ob, als, obwohl…) send the conjugated verb to the end of their clause. A comma always separates the clauses. If the subordinate clause comes first, the main clause starts with its verb (verb, verb).","Konjungsi subordinatif (weil, dass, wenn, ob, als, obwohl…) mengirim kata kerja terkonjugasi ke akhir klausanya. Koma selalu memisahkan klausa. Jika anak kalimat di depan, induk kalimat dimulai dengan kata kerjanya (kata kerja, kata kerja)."],"pattern":[{"head":[["Main clause","Induk kalimat"],["Subordinate clause (verb last)","Anak kalimat (kata kerja di akhir)"]],"rows":[["Ich bleibe zu Hause,","{weil} ich krank {bin}."],["Ich glaube,","{dass} er morgen {kommt}."],["Ruf mich an,","{wenn} du Zeit {hast}."],["Er sagt,","{dass} er nicht kommen {kann}."],[["subordinate first:","anak kalimat di depan:"],"{Wenn} es {regnet}, {bleiben} wir zu Hause."]],"note":["Separable verbs join together at the end: …, weil ich früh aufstehe.","Kata kerja terpisah menyatu di akhir: …, weil ich früh aufstehe."]}],"examples":[["Ich lerne Deutsch, weil ich in Berlin arbeite.",["I'm learning German because I work in Berlin.","Saya belajar bahasa Jerman karena bekerja di Berlin."]],["Ich hoffe, dass du bald kommst.",["I hope (that) you come soon.","Saya harap kamu segera datang."]],["Wenn ich Zeit habe, gehe ich schwimmen.",["When I have time, I go swimming.","Kalau ada waktu, saya pergi berenang."]]],"tip":["Denn also means 'because' but keeps normal order: …, denn ich bin krank. With weil the verb goes last: …, weil ich krank bin.","Denn juga berarti 'karena' tetapi susunannya biasa: …, denn ich bin krank. Dengan weil kata kerja di akhir: …, weil ich krank bin."]},{"id":"a2-imperative","title":["Imperative","Imperatif"],"what":["The du imperative is the stem (often with no ending): komm!, mach!, warte!. Verbs with e → i / ie keep the change (gib!, lies!) but a → ä verbs don't (fahr!). Ihr uses the ihr form without the pronoun (kommt!). Sie uses the infinitive form + Sie (Kommen Sie!).","Imperatif du adalah akar kata (sering tanpa akhiran): komm!, mach!, warte!. Kata kerja e → i / ie tetap berubah (gib!, lies!) tetapi a → ä tidak (fahr!). Ihr memakai bentuk ihr tanpa kata ganti (kommt!). Sie memakai bentuk infinitif + Sie (Kommen Sie!)."],"pattern":[{"head":[["Verb","Kata kerja"],"du","ihr","Sie"],"rows":[["kommen","{Komm}!","{Kommt}!","{Kommen Sie}!"],["warten","{Warte}!","{Wartet}!","{Warten Sie}!"],["geben (e → i)","{Gib}!","{Gebt}!","{Geben Sie}!"],["fahren (a → ä)","{Fahr}!","{Fahrt}!","{Fahren Sie}!"],["aufstehen","{Steh auf}!","{Steht auf}!","{Stehen Sie auf}!"],["sein","{Sei}!","{Seid}!","{Seien Sie}!"]],"note":["Add bitte, mal or doch to soften: Komm bitte mal her!","Tambahkan bitte, mal atau doch untuk melunakkan: Komm bitte mal her!"]}],"examples":[["Mach bitte das Fenster zu!",["Please close the window!","Tolong tutup jendelanya!"]],["Seid leise, das Baby schläft!",["Be quiet (all of you), the baby is sleeping!","Diam, bayinya sedang tidur!"]],["Nehmen Sie Platz.",["Take a seat.","Silakan duduk."]]],"tip":["The du imperative never has -st and no pronoun: 'Komm!', not 'Kommst du!' or 'Komm du!'.","Imperatif du tidak pernah ber-st dan tanpa kata ganti: 'Komm!', bukan 'Kommst du!' atau 'Komm du!'."]},{"id":"a2-pronoun-cases","title":["Personal pronouns in all cases","Kata ganti orang dalam semua kasus"],"what":["Personal pronouns change for the accusative and the dative. Use the accusative after verbs with a direct object and accusative prepositions; the dative after dative verbs and prepositions, and for the receiver of something.","Kata ganti orang berubah untuk akusatif dan datif. Pakai akusatif setelah kata kerja dengan objek langsung dan kata depan akusatif; datif setelah kata kerja dan kata depan datif, serta untuk penerima sesuatu."],"pattern":[{"head":[["Nominative","Nominatif"],["Accusative","Akusatif"],["Dative","Datif"]],"rows":[["ich","{mich}","{mir}"],["du","{dich}","{dir}"],["er","{ihn}","{ihm}"],["sie","{sie}","{ihr}"],["es","{es}","{ihm}"],["wir","{uns}","{uns}"],["ihr","{euch}","{euch}"],["sie / Sie","{sie} / {Sie}","{ihnen} / {Ihnen}"]],"note":["Two pronoun objects: accusative before dative: Ich gebe es ihm.","Dua objek kata ganti: akusatif sebelum datif: Ich gebe es ihm."]}],"examples":[["Ich sehe ihn morgen.",["I'll see him tomorrow.","Saya akan bertemu dia besok."]],["Gib mir bitte das Salz.",["Pass me the salt, please.","Tolong ambilkan garam."]],["Ich komme mit dir.",["I'm coming with you.","Saya ikut denganmu."]]],"tip":["ihr can be 'you (pl.)' (nominative) or 'to her' (dative): Ihr seid nett. / Ich helfe ihr.","ihr bisa berarti 'kalian' (nominatif) atau 'kepadanya (perempuan)' (datif): Ihr seid nett. / Ich helfe ihr."]},{"id":"a2-conjunctions","title":["Und, aber, denn, sondern, deshalb, trotzdem","Und, aber, denn, sondern, deshalb, trotzdem"],"what":["Und, aber, oder, denn and sondern join two main clauses without changing the word order (they stand in 'position 0'). Deshalb, trotzdem, dann and danach are adverbs: they take position 1, so the verb comes right after them.","Und, aber, oder, denn dan sondern menggabungkan dua induk kalimat tanpa mengubah susunan kata (berada di 'posisi 0'). Deshalb, trotzdem, dann dan danach adalah kata keterangan: menempati posisi 1, jadi kata kerja langsung menyusul."],"pattern":[{"head":[["Word","Kata"],["Meaning","Arti"],["Word order","Susunan"],["Example","Contoh"]],"rows":[["{und / aber / oder}",["and / but / or","dan / tetapi / atau"],["normal","biasa"],"Ich bin müde, {aber} ich arbeite."],["{denn}",["because","karena"],["normal","biasa"],"Ich bleibe hier, {denn} es regnet."],["{sondern}",["but rather","melainkan"],["normal","biasa"],"Nicht heute, {sondern} morgen."],["{deshalb}",["that's why","karena itu"],["verb next","kata kerja menyusul"],"Es regnet, {deshalb bleibe} ich hier."],["{trotzdem}",["even so","meskipun begitu"],["verb next","kata kerja menyusul"],"Es regnet, {trotzdem gehe} ich raus."]]}],"examples":[["Ich trinke keinen Kaffee, sondern Tee.",["I don't drink coffee, but tea.","Saya tidak minum kopi, melainkan teh."]],["Ich habe Hunger, deshalb koche ich jetzt.",["I'm hungry, so I'm cooking now.","Saya lapar, karena itu saya memasak sekarang."]],["Er ist krank, trotzdem arbeitet er.",["He's ill, but he's working anyway.","Dia sakit, meskipun begitu dia bekerja."]]],"tip":["Use sondern (not aber) after a negative to correct: 'nicht rot, sondern blau'.","Pakai sondern (bukan aber) setelah negasi untuk mengoreksi: 'nicht rot, sondern blau'."]}]},{"id":"B1","name":["Intermediate","Menengah"],"goal":["Tell stories, give opinions and reasons, talk about wishes and hypotheses; understand written texts.","Bercerita, memberi pendapat dan alasan, membicarakan keinginan dan pengandaian; memahami teks tertulis."],"topics":[{"id":"b1-praeteritum","title":["Präteritum (simple past) of all verbs","Präteritum semua kata kerja"],"what":["The Präteritum is the past tense of written stories, reports and news. Weak verbs add -te- to the stem (machte). Strong verbs change their vowel and take no -te (ging, sah). Mixed verbs do both (brachte, dachte). Ich and er/sie/es never have an ending.","Präteritum adalah kala lampau dalam cerita tertulis, laporan dan berita. Kata kerja lemah menambahkan -te- pada akar (machte). Kata kerja kuat mengubah vokal tanpa -te (ging, sah). Kata kerja campuran melakukan keduanya (brachte, dachte). Bentuk ich dan er/sie/es tidak pernah berakhiran."],"pattern":[{"head":[["Person","Persona"],["machen (weak)","machen (lemah)"],["gehen (strong)","gehen (kuat)"],["denken (mixed)","denken (campuran)"]],"rows":[["ich","mach{te}","{ging}","{dach}te"],["du","mach{test}","{ging}st","{dach}test"],["er / sie / es","mach{te}","{ging}","{dach}te"],["wir","mach{ten}","{ging}en","{dach}ten"],["ihr","mach{tet}","{ging}t","{dach}tet"],["sie / Sie","mach{ten}","{ging}en","{dach}ten"]],"note":["Common strong stems: kam, sah, gab, nahm, fand, fuhr, las, sprach, schrieb, trank, stand, saß, lag, blieb, rief. The verb list of each level shows the Präteritum.","Akar kuat yang umum: kam, sah, gab, nahm, fand, fuhr, las, sprach, schrieb, trank, stand, saß, lag, blieb, rief. Daftar kata kerja tiap level menunjukkan Präteritum."]}],"examples":[["Es war einmal ein König, der hatte drei Töchter.",["Once upon a time there was a king who had three daughters.","Pada zaman dahulu ada seorang raja yang punya tiga putri."]],["Sie öffnete die Tür und sah einen Mann.",["She opened the door and saw a man.","Dia membuka pintu dan melihat seorang laki-laki."]],["Wir fuhren nach Hause.",["We drove home.","Kami pulang naik kendaraan."]]],"tip":["In speech, use the Perfekt for most verbs; use the Präteritum for sein, haben, modals and in writing.","Dalam percakapan, pakai Perfekt untuk kebanyakan kata kerja; pakai Präteritum untuk sein, haben, modal dan dalam tulisan."]},{"id":"b1-konjunktiv2","title":["Konjunktiv II: würde, wäre, hätte","Konjunktiv II: würde, wäre, hätte"],"what":["Konjunktiv II expresses unreal situations, wishes, polite requests and advice. Most verbs use würde + infinitive. Sein, haben and modal verbs use their own forms: wäre, hätte, könnte, müsste, dürfte, sollte.","Konjunktiv II menyatakan situasi tidak nyata, keinginan, permintaan sopan dan saran. Kebanyakan kata kerja memakai würde + infinitif. Sein, haben dan kata kerja modal memakai bentuk sendiri: wäre, hätte, könnte, müsste, dürfte, sollte."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"werden → würde","sein → wäre","haben → hätte","können → könnte"],"rows":[["ich","{würde} fahren","{wäre}","{hätte}","{könnte}"],["du","{würdest} fahren","{wär(e)st}","{hättest}","{könntest}"],["er / sie / es","{würde} fahren","{wäre}","{hätte}","{könnte}"],["wir","{würden} fahren","{wären}","{hätten}","{könnten}"],["ihr","{würdet} fahren","{wär(e)t}","{hättet}","{könntet}"],["sie / Sie","{würden} fahren","{wären}","{hätten}","{könnten}"]]},{"title":["Uses","Pemakaian"],"head":[["Use","Pemakaian"],["Example","Contoh"]],"rows":[[["unreal condition","syarat tidak nyata"],"{Wenn} ich Zeit {hätte}, {würde} ich mitkommen."],[["wish","keinginan"],"Ich {wäre} gern am Meer. {Wenn} ich doch reich {wäre}!"],[["polite request","permintaan sopan"],"{Könnten} Sie mir helfen? Ich {hätte} gern einen Kaffee."],[["advice","saran"],"Du {solltest} mehr schlafen. An deiner Stelle {würde} ich …"]]}],"examples":[["Wenn ich reich wäre, würde ich um die Welt reisen.",["If I were rich, I'd travel around the world.","Kalau saya kaya, saya akan keliling dunia."]],["Könnten Sie das Fenster schließen?",["Could you close the window?","Bisakah Anda menutup jendela?"]],["Du solltest zum Arzt gehen.",["You should go to the doctor.","Kamu sebaiknya ke dokter."]]],"tip":["Don't put würde in both clauses of an 'if' sentence with sein/haben: 'Wenn ich Zeit hätte, würde ich kommen' (not 'würde haben').","Jangan memakai würde di kedua klausa dengan sein/haben: 'Wenn ich Zeit hätte, würde ich kommen' (bukan 'würde haben')."]},{"id":"b1-passive","title":["Passive voice (werden + Partizip II)","Kalimat pasif (werden + Partizip II)"],"what":["The passive focuses on the action, not on who does it. Present: werden + Partizip II. Präteritum: wurde + Partizip II. Perfekt: ist + Partizip II + worden. The doer, if mentioned, takes von + dative.","Kalimat pasif berfokus pada tindakan, bukan pelakunya. Kini: werden + Partizip II. Präteritum: wurde + Partizip II. Perfekt: ist + Partizip II + worden. Pelaku, jika disebut, memakai von + datif."],"pattern":[{"head":[["Tense","Kala"],["Passive","Pasif"],["Example","Contoh"]],"rows":[[["present","kini"],"{wird / werden} + Partizip II","Das Haus {wird} renoviert."],[["Präteritum","Präteritum"],"{wurde / wurden} + Partizip II","Das Haus {wurde} 1900 gebaut."],[["Perfekt","Perfekt"],"{ist / sind} + Partizip II + {worden}","Das Haus {ist} verkauft {worden}."],[["with a modal","dengan modal"],"Modal + Partizip II + {werden}","Das Haus {muss} renoviert {werden}."],[["doer","pelaku"],"{von} + dative","Das Buch wurde {von} einer Studentin geschrieben."]]}],"examples":[["Hier wird Deutsch gesprochen.",["German is spoken here.","Di sini dipakai bahasa Jerman."]],["Der Brief wurde gestern geschickt.",["The letter was sent yesterday.","Surat itu dikirim kemarin."]],["Das Auto ist repariert worden.",["The car has been repaired.","Mobilnya sudah diperbaiki."]]],"tip":["In the passive Perfekt it's worden, not geworden: 'Das ist gemacht worden'. Geworden means 'become'.","Dalam Perfekt pasif dipakai worden, bukan geworden: 'Das ist gemacht worden'. Geworden berarti 'menjadi'."]},{"id":"b1-relative","title":["Relative clauses (der, die, das)","Anak kalimat relatif (der, die, das)"],"what":["Relative pronouns look like the definite article (except dative plural denen and genitive dessen/deren). Gender and number come from the noun they refer to; the case comes from their role in the relative clause. The verb goes to the end.","Kata ganti relatif mirip artikel takrif (kecuali datif jamak denen dan genitif dessen/deren). Gender dan jumlah mengikuti kata benda yang dirujuk; kasusnya mengikuti fungsinya dalam anak kalimat relatif. Kata kerja di akhir."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["nominative","nominatif"],"der","die","das","die"],[["accusative","akusatif"],"{den}","die","das","die"],[["dative","datif"],"{dem}","{der}","{dem}","{denen}"],[["genitive","genitif"],"{dessen}","{deren}","{dessen}","{deren}"]]},{"title":["Examples","Contoh"],"head":[["Role in the relative clause","Fungsi dalam anak kalimat"],["Sentence","Kalimat"]],"rows":[[["subject","subjek"],"Der Mann, {der} dort steht, ist mein Chef."],[["accusative object","objek akusatif"],"Der Mann, {den} ich gestern gesehen habe, …"],[["dative object","objek datif"],"Der Mann, {dem} ich geholfen habe, …"],[["after a preposition","setelah kata depan"],"Die Freunde, mit {denen} ich wohne, …"]]}],"examples":[["Das ist die Frau, die neben mir wohnt.",["That's the woman who lives next to me.","Itu perempuan yang tinggal di sebelah saya."]],["Wo ist das Buch, das ich gekauft habe?",["Where's the book I bought?","Di mana buku yang saya beli?"]],["Die Stadt, in der ich geboren bin, ist klein.",["The town I was born in is small.","Kota tempat saya lahir itu kecil."]]],"tip":["Unlike English, the relative pronoun can never be left out, and the preposition always comes before it: die Stadt, in der ich wohne.","Kata ganti relatif tidak boleh dihilangkan, dan kata depan selalu sebelumnya: die Stadt, in der ich wohne."]},{"id":"b1-genitive","title":["The genitive case","Kasus genitif"],"what":["The genitive shows possession ('of', ''s'). Masculine and neuter use des + -(e)s on the noun; feminine and plural use der. With names, add -s: Annas Auto. In speech von + dative is often used instead. Some prepositions take the genitive: wegen, trotz, während, statt.","Genitif menunjukkan kepemilikan ('milik'). Maskulin dan netral memakai des + -(e)s pada kata benda; feminin dan jamak memakai der. Dengan nama, tambahkan -s: Annas Auto. Dalam percakapan sering dipakai von + datif. Beberapa kata depan diikuti genitif: wegen, trotz, während, statt."],"pattern":[{"head":["",["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["definite","takrif"],"{des} Mann{es}","{der} Frau","{des} Kind{es}","{der} Kinder"],[["indefinite","taktakrif"],"{eines} Mann{es}","{einer} Frau","{eines} Kind{es}",["— (von Kindern)","— (von Kindern)"]],[["possessive","kepemilikan"],"{meines} Vater{s}","{meiner} Mutter","{meines} Auto{s}","{meiner} Eltern"]],"note":["Short masculine/neuter nouns often take -es (des Mannes), longer ones -s (des Vaters).","Kata benda maskulin/netral pendek sering -es (des Mannes), yang panjang -s (des Vaters)."]}],"examples":[["Das ist das Auto meines Vaters.",["That's my father's car.","Itu mobil ayah saya."]],["Wegen des Regens bleiben wir zu Hause.",["Because of the rain we're staying at home.","Karena hujan kami tinggal di rumah."]],["Während der Woche arbeite ich viel.",["During the week I work a lot.","Selama seminggu saya banyak bekerja."]]],"tip":["No apostrophe with names: Annas Buch, not 'Anna's Buch'. In conversation 'das Buch von Anna' is fine.","Tanpa apostrof untuk nama: Annas Buch, bukan 'Anna's Buch'. Dalam percakapan 'das Buch von Anna' juga boleh."]},{"id":"b1-zu-infinitive","title":["Infinitive with zu","Infinitif dengan zu"],"what":["After many verbs (versuchen, vergessen, anfangen, aufhören, hoffen), nouns (Lust, Zeit, Angst) and adjectives (es ist wichtig/schön/schwer), the second verb is zu + infinitive at the end. With separable verbs zu goes between prefix and verb: anzurufen. Modal verbs never take zu.","Setelah banyak kata kerja (versuchen, vergessen, anfangen, aufhören, hoffen), kata benda (Lust, Zeit, Angst) dan kata sifat (es ist wichtig/schön/schwer), kata kerja kedua berbentuk zu + infinitif di akhir. Dengan kata kerja terpisah, zu diletakkan di antara awalan dan kata kerja: anzurufen. Kata kerja modal tidak pernah memakai zu."],"pattern":[{"head":[["After…","Setelah…"],["Example","Contoh"]],"rows":[[["verb","kata kerja"],"Ich versuche, pünktlich {zu} sein. Er hat vergessen, mich {anzurufen}."],[["noun","kata benda"],"Hast du Lust, ins Kino {zu} gehen? Ich habe keine Zeit, {zu} kochen."],[["adjective","kata sifat"],"Es ist wichtig, viel Wasser {zu} trinken."],[["modal: no zu","modal: tanpa zu"],"Ich muss arbeiten. (not: zu arbeiten)"]]}],"examples":[["Ich habe angefangen, Spanisch zu lernen.",["I've started learning Spanish.","Saya sudah mulai belajar bahasa Spanyol."]],["Es ist schwer, eine Wohnung zu finden.",["It's hard to find a flat.","Sulit menemukan apartemen."]],["Vergiss nicht, das Licht auszumachen!",["Don't forget to switch off the light!","Jangan lupa mematikan lampu!"]]],"tip":["Never zu after modals or after verbs like gehen, lassen, bleiben: 'Ich gehe einkaufen', 'Ich lasse das Auto reparieren'.","Jangan pakai zu setelah modal atau kata kerja seperti gehen, lassen, bleiben: 'Ich gehe einkaufen', 'Ich lasse das Auto reparieren'."]},{"id":"b1-um-zu-damit","title":["Purpose: um … zu and damit","Tujuan: um … zu dan damit"],"what":["Both mean 'in order to / so that'. Use um … zu + infinitive when the subject of both parts is the same. Use damit + a clause (verb at the end) when the subjects are different (damit is also possible with the same subject).","Keduanya berarti 'supaya / untuk'. Pakai um … zu + infinitif jika subjek kedua bagian sama. Pakai damit + klausa (kata kerja di akhir) jika subjeknya berbeda (damit juga boleh dengan subjek yang sama)."],"pattern":[{"head":[["Subjects","Subjek"],["Pattern","Pola"],["Example","Contoh"]],"rows":[[["same","sama"],"{um} … {zu} + infinitive","Ich lerne Deutsch, {um} in Berlin {zu} arbeiten."],[["different","berbeda"],"{damit} + subject + … + verb","Ich spreche langsam, {damit} du mich {verstehst}."],[["separable verb","kata kerja terpisah"],"{um} … {-zu-}","Ich stehe früh auf, {um} den Bus nicht {zu} verpassen."],[["question","pertanyaan"],"{Wozu?} / {Wofür?}","Wozu brauchst du das? — Um Brot zu backen."]]}],"examples":[["Ich spare Geld, um ein Auto zu kaufen.",["I'm saving money to buy a car.","Saya menabung untuk membeli mobil."]],["Wir sprechen leise, damit das Baby schläft.",["We're speaking quietly so that the baby sleeps.","Kami berbicara pelan supaya bayinya tidur."]],["Er geht früh ins Bett, um fit zu sein.",["He goes to bed early to be fit.","Dia tidur lebih awal supaya bugar."]]],"tip":["English 'for + -ing' is um … zu: 'Ich brauche Geld, um zu reisen' (not 'für reisen').","'Untuk + kata kerja' adalah um … zu: 'Ich brauche Geld, um zu reisen' (bukan 'für reisen')."]},{"id":"b1-plusquamperfekt","title":["Plusquamperfekt (past perfect)","Plusquamperfekt (lampau sempurna)"],"what":["Hatte or war + Partizip II tells what had happened before another past event. It is common after nachdem: Nachdem ich gegessen hatte, ging ich spazieren.","Hatte atau war + Partizip II menceritakan apa yang sudah terjadi sebelum peristiwa lampau lainnya. Sering dipakai setelah nachdem: Nachdem ich gegessen hatte, ging ich spazieren."],"pattern":[{"head":[["Person","Persona"],["with haben","dengan haben"],["with sein","dengan sein"]],"rows":[["ich","{hatte} gegessen","{war} gegangen"],["du","{hattest} gegessen","{warst} gegangen"],["er / sie / es","{hatte} gegessen","{war} gegangen"],["wir","{hatten} gegessen","{waren} gegangen"],["ihr","{hattet} gegessen","{wart} gegangen"],["sie / Sie","{hatten} gegessen","{waren} gegangen"]]},{"title":["With nachdem","Dengan nachdem"],"head":[["Earlier (Plusquamperfekt)","Lebih dulu (Plusquamperfekt)"],["Later (Präteritum / Perfekt)","Kemudian (Präteritum / Perfekt)"]],"rows":[["{Nachdem} er {angekommen war},","rief er mich an."],["{Nachdem} wir {gegessen hatten},","sind wir ins Kino gegangen."]]}],"examples":[["Als ich ankam, war der Zug schon abgefahren.",["When I arrived, the train had already left.","Ketika saya tiba, keretanya sudah berangkat."]],["Ich hatte vergessen, dass heute Sonntag ist.",["I had forgotten that today is Sunday.","Saya lupa bahwa hari ini hari Minggu."]],["Nachdem sie die Prüfung bestanden hatte, feierte sie.",["After she had passed the exam, she celebrated.","Setelah lulus ujian, dia merayakannya."]]],"tip":["Use the same helper as in the Perfekt: ich bin gegangen → ich war gegangen; ich habe gegessen → ich hatte gegessen.","Pakai kata bantu yang sama dengan Perfekt: ich bin gegangen → ich war gegangen; ich habe gegessen → ich hatte gegessen."]},{"id":"b1-n-declension","title":["N-declension (weak masculine nouns)","Deklinasi -n (kata benda maskulin lemah)"],"what":["A group of masculine nouns adds -(e)n in every case except the nominative singular: der Kollege → den Kollegen, dem Kollegen. They include nouns for people and animals ending in -e (der Junge, der Kunde, der Löwe), and nouns in -ent, -ant, -ist (der Student, der Präsident, der Polizist), plus der Herr, der Mensch, der Nachbar.","Sekelompok kata benda maskulin ditambah -(e)n di semua kasus kecuali nominatif tunggal: der Kollege → den Kollegen, dem Kollegen. Termasuk kata benda untuk orang dan hewan berakhiran -e (der Junge, der Kunde, der Löwe), kata benda -ent, -ant, -ist (der Student, der Präsident, der Polizist), serta der Herr, der Mensch, der Nachbar."],"pattern":[{"head":[["Case","Kasus"],"der Kollege","der Student","der Herr"],"rows":[[["nominative","nominatif"],"der Kollege","der Student","der Herr"],[["accusative","akusatif"],"den Kollege{n}","den Student{en}","den Herr{n}"],[["dative","datif"],"dem Kollege{n}","dem Student{en}","dem Herr{n}"],[["genitive","genitif"],"des Kollege{n}","des Student{en}","des Herr{n}"],[["plural (all cases)","jamak (semua kasus)"],"die Kollege{n}","die Student{en}","die Herr{en}"]]}],"examples":[["Ich frage den Kollegen.",["I'll ask the colleague.","Saya akan bertanya kepada rekan itu."]],["Kennst du den neuen Studenten?",["Do you know the new student?","Kamu kenal mahasiswa baru itu?"]],["Ich spreche mit Herrn Müller.",["I'm talking to Mr Müller.","Saya berbicara dengan Pak Müller."]]],"tip":["Even in a letter: 'Sehr geehrter Herr Klein' (nominative) but 'an Herrn Klein' (accusative).","Bahkan dalam surat: 'Sehr geehrter Herr Klein' (nominatif) tetapi 'an Herrn Klein' (akusatif)."]},{"id":"b1-adj-no-article","title":["Adjective endings without an article","Akhiran kata sifat tanpa artikel"],"what":["When there is no article before the adjective, the adjective itself takes the ending the definite article would have shown (strong endings): kalter Kaffee (der), kalte Milch (die), kaltes Wasser (das). Exception: masculine and neuter genitive take -en.","Jika tidak ada artikel sebelum kata sifat, kata sifat sendiri memakai akhiran yang biasanya ditunjukkan artikel takrif (akhiran kuat): kalter Kaffee (der), kalte Milch (die), kaltes Wasser (das). Pengecualian: genitif maskulin dan netral memakai -en."],"pattern":[{"head":[["Case","Kasus"],["masculine","maskulin"],["feminine","feminin"],["neuter","netral"],["plural","jamak"]],"rows":[[["nominative","nominatif"],"kalt{er} Kaffee","kalt{e} Milch","kalt{es} Wasser","kalt{e} Getränke"],[["accusative","akusatif"],"kalt{en} Kaffee","kalt{e} Milch","kalt{es} Wasser","kalt{e} Getränke"],[["dative","datif"],"mit kalt{em} Kaffee","mit kalt{er} Milch","mit kalt{em} Wasser","mit kalt{en} Getränken"]],"note":["Same after numbers and words like viele, einige, wenige in the plural: zwei kleine Kinder, viele neue Freunde.","Sama setelah angka dan kata seperti viele, einige, wenige dalam jamak: zwei kleine Kinder, viele neue Freunde."]}],"examples":[["Ich trinke gern heißen Tee.",["I like drinking hot tea.","Saya suka minum teh panas."]],["Frisches Brot schmeckt am besten.",["Fresh bread tastes best.","Roti segar paling enak."]],["Mit freundlichen Grüßen",["Kind regards (letter ending)","Hormat saya (penutup surat)"]]],"tip":["Think 'the adjective takes over the article's job': der → -er, den → -en, dem → -em, das → -es, die → -e.","Ingat 'kata sifat mengambil alih tugas artikel': der → -er, den → -en, dem → -em, das → -es, die → -e."]},{"id":"b1-prep-verbs","title":["Verbs with prepositions; da- and wo- words","Kata kerja dengan kata depan; kata da- dan wo-"],"what":["Many verbs have a fixed preposition and case: warten auf (+ acc.), denken an (+ acc.), sich interessieren für (+ acc.), sprechen über (+ acc.), träumen von (+ dat.), Angst haben vor (+ dat.). For things, replace preposition + noun with da(r)- + preposition (darauf, daran) and ask with wo(r)- (worauf?). For people use the preposition + pronoun.","Banyak kata kerja punya kata depan dan kasus tetap: warten auf (+ akus.), denken an (+ akus.), sich interessieren für (+ akus.), sprechen über (+ akus.), träumen von (+ dat.), Angst haben vor (+ dat.). Untuk benda, ganti kata depan + kata benda dengan da(r)- + kata depan (darauf, daran) dan tanyakan dengan wo(r)- (worauf?). Untuk orang pakai kata depan + kata ganti."],"pattern":[{"head":[["Verb","Kata kerja"],["Thing (da- / wo-)","Benda (da- / wo-)"],["Person","Orang"]],"rows":[["warten {auf} + acc.","{Worauf} wartest du? — Ich warte {darauf}.","Auf wen wartest du? — Auf {ihn}."],["denken {an} + acc.","{Woran} denkst du? — Ich denke {daran}.","An wen denkst du? — An {dich}."],["sich interessieren {für} + acc.","{Wofür} interessierst du dich? — {Dafür}.","Für wen? — Für {sie}."],["sprechen {über} + acc.","{Worüber} sprecht ihr? — {Darüber}.","Über wen? — Über {ihn}."],["träumen {von} + dat.","{Wovon} träumst du? — {Davon}.","Von wem? — Von {ihr}."]],"note":["An r is added before a vowel: dar-auf, wor-an, dar-über.","Huruf r ditambahkan sebelum vokal: dar-auf, wor-an, dar-über."]}],"examples":[["Ich warte auf den Bus.",["I'm waiting for the bus.","Saya menunggu bus."]],["Denkst du an meinen Geburtstag? — Ja, ich denke daran.",["Will you remember my birthday? — Yes, I will.","Kamu ingat ulang tahun saya? — Ya, saya ingat."]],["Worüber habt ihr gesprochen?",["What did you talk about?","Kalian membicarakan apa?"]]],"tip":["Learn the preposition with the verb, like a vocabulary pair: sich freuen auf, Angst haben vor, teilnehmen an.","Hafalkan kata depan bersama kata kerjanya seperti pasangan kosakata: sich freuen auf, Angst haben vor, teilnehmen an."]},{"id":"b1-als-wenn","title":["Als, wenn and wann","Als, wenn dan wann"],"what":["All three can translate 'when'. Als = a single event or period in the past. Wenn = repeated events (whenever), present or future events, and conditions (if). Wann = question word ('at what time?'), also in indirect questions.","Ketiganya bisa berarti 'ketika / kapan'. Als = satu peristiwa atau periode di masa lalu. Wenn = peristiwa berulang (setiap kali), peristiwa kini atau masa depan, dan syarat (jika). Wann = kata tanya ('kapan?'), juga dalam pertanyaan tidak langsung."],"pattern":[{"head":[["Word","Kata"],["Use","Pemakaian"],["Example","Contoh"]],"rows":[["{als}",["once, in the past","sekali, di masa lalu"],"{Als} ich zehn war, zogen wir nach Wien."],["{wenn}",["every time (past or present)","setiap kali (lampau atau kini)"],"{Wenn} ich Oma besuchte, backte sie Kuchen."],["{wenn}",["future / condition","masa depan / syarat"],"{Wenn} ich fertig bin, rufe ich dich an."],["{wann}",["question","pertanyaan"],"{Wann} kommst du? Weißt du, {wann} er kommt?"]]}],"examples":[["Als ich in Berlin ankam, regnete es.",["When I arrived in Berlin, it was raining.","Ketika saya tiba di Berlin, sedang hujan."]],["Wenn es regnet, nehme ich den Bus.",["When(ever) it rains, I take the bus.","Kalau hujan, saya naik bus."]],["Ich weiß nicht, wann der Film beginnt.",["I don't know when the film starts.","Saya tidak tahu kapan filmnya mulai."]]],"tip":["Ask yourself: one time in the past? → als. Several times, now or later? → wenn. A question? → wann.","Tanyakan: sekali di masa lalu? → als. Berkali-kali, sekarang atau nanti? → wenn. Pertanyaan? → wann."]},{"id":"b1-indirect-questions","title":["Indirect questions (ob, wo, wann…)","Pertanyaan tidak langsung (ob, wo, wann…)"],"what":["After Ich weiß nicht, Können Sie mir sagen, Ich frage mich…, a question becomes a subordinate clause with the verb at the end. W-questions keep the question word; yes/no questions use ob (whether).","Setelah Ich weiß nicht, Können Sie mir sagen, Ich frage mich…, pertanyaan menjadi anak kalimat dengan kata kerja di akhir. Pertanyaan W tetap memakai kata tanyanya; pertanyaan ya/tidak memakai ob (apakah)."],"pattern":[{"head":[["Direct","Langsung"],["Indirect","Tidak langsung"]],"rows":[["Wo ist der Bahnhof?","Können Sie mir sagen, {wo} der Bahnhof {ist}?"],["Wann beginnt der Kurs?","Ich weiß nicht, {wann} der Kurs {beginnt}."],["Kommt er morgen?","Ich frage mich, {ob} er morgen {kommt}."],["Hast du Zeit?","Er will wissen, {ob} du Zeit {hast}."]]}],"examples":[["Wissen Sie, wie spät es ist?",["Do you know what time it is?","Anda tahu jam berapa sekarang?"]],["Ich weiß nicht, ob ich kommen kann.",["I don't know whether I can come.","Saya tidak tahu apakah saya bisa datang."]],["Kannst du mir sagen, was das kostet?",["Can you tell me what that costs?","Bisakah kamu memberi tahu saya berapa harganya?"]]],"tip":["'Whether / if' in an indirect question is ob, never wenn: 'Ich weiß nicht, ob er kommt'.","'Apakah' dalam pertanyaan tidak langsung adalah ob, bukan wenn: 'Ich weiß nicht, ob er kommt'."]},{"id":"b1-two-part-conj","title":["Two-part conjunctions","Konjungsi dua bagian"],"what":["Some conjunctions come in pairs: sowohl … als auch (both … and), entweder … oder (either … or), weder … noch (neither … nor), nicht nur … sondern auch (not only … but also), zwar … aber (it's true … but), je … desto (the more … the more).","Beberapa konjungsi berpasangan: sowohl … als auch (baik … maupun), entweder … oder (atau … atau), weder … noch (bukan … maupun), nicht nur … sondern auch (tidak hanya … tetapi juga), zwar … aber (memang … tetapi), je … desto (semakin … semakin)."],"pattern":[{"head":[["Pair","Pasangan"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{sowohl} … {als auch}",["both … and","baik … maupun"],"Er spricht {sowohl} Englisch {als auch} Französisch."],["{entweder} … {oder}",["either … or","atau … atau"],"{Entweder} kommst du mit, {oder} du bleibst hier."],["{weder} … {noch}",["neither … nor","bukan … maupun"],"Ich trinke {weder} Kaffee {noch} Tee."],["{nicht nur} … {sondern auch}",["not only … but also","tidak hanya … tetapi juga"],"Sie ist {nicht nur} klug, {sondern auch} nett."],["{zwar} … {aber}",["it's true … but","memang … tetapi"],"Das Hotel ist {zwar} teuer, {aber} schön."],["{je} + comp. … {desto} + comp.",["the more … the more","semakin … semakin"],"{Je} mehr ich lerne, {desto} besser spreche ich."]],"note":["After je the verb goes to the end; after desto + comparative comes the verb: Je älter er wird, desto ruhiger ist er.","Setelah je kata kerja di akhir; setelah desto + komparatif langsung kata kerja: Je älter er wird, desto ruhiger ist er."]}],"examples":[["Wir können entweder heute oder morgen fahren.",["We can go either today or tomorrow.","Kita bisa berangkat hari ini atau besok."]],["Ich habe weder Zeit noch Geld.",["I have neither time nor money.","Saya tidak punya waktu maupun uang."]],["Je früher wir losfahren, desto besser.",["The earlier we leave, the better.","Semakin cepat kita berangkat, semakin baik."]]],"tip":["Weder … noch is already negative: never add nicht or kein to it.","Weder … noch sudah negatif: jangan tambahkan nicht atau kein."]},{"id":"b1-futur","title":["Future tense (werden + infinitive)","Kala depan (werden + infinitif)"],"what":["Werden + infinitive at the end forms the future. German often uses the present with a time word instead (Morgen fahre ich). The Futur is used for promises, predictions, plans stressed as future, and with wohl for guesses about the present.","Werden + infinitif di akhir membentuk kala depan. Bahasa Jerman sering memakai kala kini dengan kata waktu (Morgen fahre ich). Futur dipakai untuk janji, prediksi, rencana yang ditekankan sebagai masa depan, dan dengan wohl untuk dugaan tentang saat ini."],"pattern":[{"head":[["Person","Persona"],"werden",["Example","Contoh"]],"rows":[["ich","{werde}","Ich {werde} dich anrufen."],["du","{wirst}","Du {wirst} das schaffen!"],["er / sie / es","{wird}","Es {wird} morgen regnen."],["wir","{werden}","Wir {werden} im Mai heiraten."],["ihr","{werdet}","Ihr {werdet} sehen."],["sie / Sie","{werden}","Sie {werden} wohl zu Hause sein. (guess)"]],"note":["Werden + adjective/noun = become: Es wird kalt. Er wird Arzt.","Werden + kata sifat/benda = menjadi: Es wird kalt. Er wird Arzt."]}],"examples":[["Ich werde nächstes Jahr in Wien studieren.",["I'll study in Vienna next year.","Tahun depan saya akan kuliah di Wina."]],["Das wird schon klappen.",["It'll work out.","Pasti akan berhasil."]],["Er wird wohl krank sein.",["He's probably ill.","Mungkin dia sakit."]]],"tip":["'Ich will' means 'I want', not 'I will': 'Ich will nach Hause' = I want to go home. 'I will' is ich werde.","'Ich will' berarti 'saya mau', bukan 'saya akan': 'Ich will nach Hause' = saya mau pulang. 'Saya akan' adalah ich werde."]},{"id":"b1-obwohl-trotzdem","title":["Concession: obwohl and trotzdem","Konsesi: obwohl dan trotzdem"],"what":["Obwohl (although) is a subordinating conjunction: the verb goes to the end. Trotzdem (even so, nevertheless) is an adverb: it stands in position 1 or in the middle, and the verb comes right after it when it is first. Trotz + genitive is the preposition 'despite'.","Obwohl (meskipun) adalah konjungsi subordinatif: kata kerja di akhir. Trotzdem (meskipun begitu) adalah kata keterangan: di posisi 1 atau di tengah, dan kata kerja langsung menyusul jika ia di depan. Trotz + genitif adalah kata depan 'walaupun ada'."],"pattern":[{"head":[["Word","Kata"],["Word order","Susunan"],["Example","Contoh"]],"rows":[["{obwohl}",["verb at the end","kata kerja di akhir"],"Ich gehe raus, {obwohl} es {regnet}."],["{obwohl} (first)",["main clause starts with its verb","induk kalimat dimulai dengan kata kerja"],"{Obwohl} es regnet, {gehe} ich raus."],["{trotzdem}",["verb right after it","kata kerja langsung menyusul"],"Es regnet. {Trotzdem gehe} ich raus."],["{trotz} + genitive",["preposition","kata depan"],"{Trotz des} Regens gehe ich raus."]]}],"examples":[["Obwohl er müde war, arbeitete er weiter.",["Although he was tired, he kept working.","Meskipun lelah, dia terus bekerja."]],["Das Wetter war schlecht. Trotzdem hatten wir Spaß.",["The weather was bad. Even so, we had fun.","Cuacanya buruk. Meskipun begitu kami bersenang-senang."]],["Trotz der Kälte gingen wir spazieren.",["Despite the cold we went for a walk.","Walaupun dingin kami berjalan-jalan."]]],"tip":["Weil gives a reason, obwohl gives a contrast: 'weil es regnet' (because) / 'obwohl es regnet' (although).","Weil memberi alasan, obwohl memberi kontras: 'weil es regnet' (karena) / 'obwohl es regnet' (meskipun)."]}]}]};
